(function(){
  function build(paths){
    var root={children:{}, order:[]};
    for(var i=0;i<paths.length;i++){
      var parts=paths[i].split('/');
      var node=root;
      for(var j=0;j<parts.length;j++){
        var name=parts[j];
        if(name==='') continue;
        if(!node.children[name]){ node.children[name]={name:name, children:{}, order:[]}; node.order.push(name); }
        node=node.children[name];
      }
    }
    return root;
  }
  function render(node, prefix, out){
    var keys=node.order;
    for(var i=0;i<keys.length;i++){
      var k=keys[i], child=node.children[k], last=(i===keys.length-1);
      var branch= last?'└── ':'├── ';
      out.push(prefix+branch+k+(Object.keys(child.children).length?'/':''));
      var cp=prefix+(last?'    ':'│   ');
      render(child, cp, out);
    }
  }
  function tree(text){
    var paths=String(text||'').split(/\r?\n/).map(function(s){return s.trim();}).filter(function(s){return s;});
    var root=build(paths), out=[];
    out.push('.');
    render(root, '', out);
    return {value: out.join('\n')};
  }
  var API={tree:tree, build:build};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__EzaForge__=API;
})();
